// === Tab: mySketch ===
const str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890-^\=~|!\"#$%&'()'@[]:;./,_`{}*+_?><"
const NUM = 200;
let myFont;
let words = [];
let circleFlg = true;

function preload() {
 myFont = loadFont("https://stat.neort.io/externalResource/ce85p4cn70rvfbj84ag0.ttf");
}


function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  textFont(myFont);
  textAlign(CENTER, CENTER);
  for (let i = 0; i < NUM; i++) {
    words.push(new Word())
  }
}

function draw() {
  background(0);
  stroke(255);
  randomSeed(99)

  for (let word of words) {
    push()
    word.update()
    word.show()
    pop()
  }
}

class Word {
  constructor() {
    this.x = random(-width / 2, width / 2);
    this.y = random(-height / 2, height / 2);
		this.speed = random(2, 5);
    this.fontSize = int(random(15, 100))
    this.angle = random();
    this.angleSpeed = random(-0.3, 0.3);
    this.c = random(str.split(''));
    this.color = color(random(150, 255), random(150, 255), random(150, 255))
  }

  update() {
    this.angle += this.angleSpeed;
		this.y += this.speed;
		if (this.y > height / 2) this.y = -height / 2;
  }

  show() {
		if (!circleFlg) {
			translate(this.x, this.y, -100);
		}
    fill(this.color);
    textSize(this.fontSize);
    rotateX(this.angle);
    rotateY(this.angle);
    rotateZ(this.angle);
		if (circleFlg) {
			text(this.c, this.x, this.y);
		} else {
			text(this.c, 0, 0);
		}
  }
}

function mousePressed() {
  circleFlg = !circleFlg;	
}

function keyPressed() {
	if (key === "s") {
		saveGif("mySketch", 3);
	}
	if (key === "c") {
		saveCanvas("mySketch", "png");
	}
}

